import itertools

def is_kawaii(seq):
    elements = set(seq)
    for k in elements:
        if k >= 2:
            if k - 1 not in elements:
                return False
            # find first occurrence of k-1 and last occurrence of k
            first_k_minus_1 = -1
            for i, val in enumerate(seq):
                if val == k - 1:
                    first_k_minus_1 = i
                    break
            last_k = -1
            for i in range(len(seq) - 1, -1, -1):
                if seq[i] == k:
                    last_k = i
                    break
            if first_k_minus_1 >= last_k:
                return False
    return True

def count_kawaii(n, S):
    count = 0
    for seq in itertools.product(S, repeat=n):
        if is_kawaii(seq):
            count += 1
    return count

for n in range(1, 6):
    S = list(range(1, n + 2))
    print(f"n={n}, S={S}, count={count_kawaii(n, S)}")

